import{_ as t,o as a,c as s,ak as n}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Use the Chainy team board","description":"Open the team board and sign in with your own account: sherwin, christian, luis, sean or miguel. Choose a new password on first sign-in. Sherwin holds the private account hand","frontmatter":{"title":"Use the Chainy team board","description":"Open the team board and sign in with your own account: sherwin, christian, luis, sean or miguel. Choose a new password on first sign-in. Sherwin holds the private account hand","source":"docs/team-board-guide.md","category":"Other documents","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/team-board-guide.md","filePath":"content/docs/team-board-guide.md"}'),o={name:"content/docs/team-board-guide.md"};function r(i,e,d,h,c,l){return a(),s("div",null,[...e[0]||(e[0]=[n('<div><h1 id="use-the-chainy-team-board">Use the Chainy team board<a class="header-anchor" href="#use-the-chainy-team-board" aria-label="Link to this section">​</a></h1><p>Open the <a href="https://owenlim225.github.io/Chainy-Docs/board/">team board</a> and sign in with your own account: <strong>sherwin, christian, luis, sean or miguel</strong>. Choose a new password on first sign-in. Sherwin holds the private account handoff and can arrange a reset. Do not share accounts; history needs to identify the person doing the work.</p><h2 id="find-and-move-work">Find and move work<a class="header-anchor" href="#find-and-move-work" aria-label="Link to this section">​</a></h2><ul><li><strong>Board:</strong> drag a card between To do, In progress and Done. Drag above another card to reorder it. On a phone or with a keyboard, open the card and change Status or Card order within this status.</li><li><strong>My tasks:</strong> shows the work you lead. Use Person and Any involvement to include support and review work.</li><li><strong>Add task:</strong> name the result, choose a lead and reviewer, set dates and explain what “done” means.</li><li><strong>Open a card:</strong> edit its instructions, people, dates, prerequisites and evidence. Save changes before closing it.</li><li><strong>Done:</strong> use this after the agreed output is available and reviewed. A card count does not measure the school’s completion requirement.</li></ul><h2 id="adjust-the-schedule">Adjust the schedule<a class="header-anchor" href="#adjust-the-schedule" aria-label="Link to this section">​</a></h2><p><strong>Timeline</strong> is the editable Gantt view. Drag the middle of a bar to shift its dates, or an edge to change its start or finish. Open the task to enter exact dates. Scroll sideways to see later days; choose Whole project for dates after pre-final.</p><p>Changing a task does not automatically move its prerequisites or other tasks. Open the card to check prerequisite warnings and resolve date overlaps with its lead. Color identifies the lead; gray bars are Done.</p><p><strong>November 3–6 beta testing and November 21, 2026 pre-final defense are fixed.</strong> Their event markers do not move when task dates change. Protect integration, device testing and rehearsal time.</p><h2 id="understand-saved-changes">Understand saved changes<a class="header-anchor" href="#understand-saved-changes" aria-label="Link to this section">​</a></h2><p>The board checks for teammates’ changes every 10 seconds while it is open. Refresh checks immediately. A save succeeds only after the shared service accepts it. An offline error means the change has not been confirmed; reconnect and retry.</p><p>If someone changed the same card first, your edit is held in the open form and a conflict message appears. Copy any text you need, close and reopen the card, then apply your changes to the latest version.</p><p><strong>History</strong> shows the person, action, card, changed fields, location (Board, Timeline, Task details or Trash), and time in Manila. Each card also has its own history. Imported tasks are attributed to Project setup, not to a teammate.</p><h2 id="delete-restore-and-keep-a-copy">Delete, restore and keep a copy<a class="header-anchor" href="#delete-restore-and-keep-a-copy" aria-label="Link to this section">​</a></h2><p>Delete task moves the card to <strong>Trash</strong>. Anyone can open it there and choose Restore task. Its history remains. Tasks that depend on a deleted card show a warning until it is restored or their prerequisite is changed.</p><p><strong>Export backup</strong> downloads the current tasks and history as JSON. Store it with the team’s restricted project working files. Account passwords and session tokens are never included. Recovery from a full service outage is handled by the technical maintainer; the export button is not an import function.</p><h2 id="where-the-information-lives">Where the information lives<a class="header-anchor" href="#where-the-information-lives" aria-label="Link to this section">​</a></h2><p>The team board is the editing interface. It saves tasks and history in Cloudflare and copies task descriptions and status to the linked GitHub issue. A pending GitHub copy does not erase the board’s saved changes; the service retries it and displays the delay. Edit cards in the board so named history stays complete. Direct GitHub edits are not imported and can be replaced by the next board update.</p><p>Trello is disconnected. The documentation library remains public; reading or changing shared task data requires a team sign-in. The management service is separate from the game’s offline SQLite database. Keep participant records, identity maps, passwords and signing keys out of cards, evidence fields and GitHub issues.</p></div>',1)])])}const g=t(o,[["render",r]]);export{u as __pageData,g as default};
